// Deterministic assembly of three known modules; no dependency installation.
// This is intentionally not a general-purpose JavaScript bundler.
import { readFileSync, writeFileSync } from 'node:fs'
import { createHash } from 'node:crypto'
import { fileURLToPath } from 'node:url'
import { resolve } from 'node:path'
const root = new URL('../dsh-html-preview/', import.meta.url)
export function buildHtmlPreview() {
  const read = path => readFileSync(new URL(path, root), 'utf8')
  const provenance = JSON.parse(read('vendor/provenance.json'))
  for (const item of provenance.files) {
    const bytes = readFileSync(new URL(`vendor/${item.file}`, root))
    if (createHash('sha256').update(bytes).digest('hex') !== item.sha256) throw Error(`Vendor hash mismatch: ${item.file}`)
  }
  const vendor = read('vendor/purify.es.mjs')
  const exportLine = 'export { purify_default as default };'
  if (vendor.split(exportLine).length !== 2) throw Error('Unexpected DOMPurify export; review build adapter')
  const purifier = vendor.replace(exportLine, 'return purify_default;').replace(/^\/\/# sourceMappingURL=.*$/m, '')
  const core = read('core.js')
  const coreExports = [...core.matchAll(/^export (?:function|const) (\w+)/gm)].map(match => match[1])
  if (!coreExports.includes('extractHtml')) throw Error('Missing extractHtml export')
  const coreBody = core.replace(/^export (?=function|const)/gm, '')
  if (/^\s*(?:import|export)\s/m.test(coreBody)) throw Error('Unsupported core module declaration')
  let client = read('client-source.js')
  const imports = [
    /^import\s*\{[^}]*\}\s*from\s*['"]\.\/core\.js['"];?\s*$/m,
    /^import DOMPurify from ['"]\.\/vendor\/purify\.es\.mjs['"];?\s*$/m,
  ]
  for (const pattern of imports) {
    if (!pattern.test(client)) throw Error(`Unexpected client import: ${pattern}`)
    client = client.replace(pattern, '')
  }
  if (/^\s*(?:import|export)\s/m.test(client)) throw Error('Unexpected client module declaration')
  return `// Generated by tools/build-html-preview.mjs; edit client-source.js / core.js.\n// Includes DOMPurify ${provenance.version}; see vendor/LICENSE-DOMPurify.\n(() => {\nconst DOMPurify = (() => {\n${purifier}\n})();\nconst { ${coreExports.join(', ')} } = (() => {\n${coreBody}\nreturn { ${coreExports.join(', ')} };\n})();\n${client}\n})();\n`
}
if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const built = buildHtmlPreview()
  const path = new URL('client.js', root)
  if (process.argv.includes('--check')) {
    if (readFileSync(path, 'utf8') !== built) throw Error('client.js is stale: run node tools/build-html-preview.mjs')
    console.log('PASS: HTML preview bundle is current; vendor hashes verified')
  } else {
    writeFileSync(path, built)
    console.log(`Built dsh-html-preview/client.js (${Buffer.byteLength(built)} bytes)`)
  }
}
